//! Writes a demo song folder to try the Perform screen with:
//!
//! ```text
//! cargo run -p multitrack-desktop --example demo_song -- <DIR>
//! ```
//!
//! 48 kHz, 120 bpm in 4/4 (a bar is 2 s). Seven sections (intro, verse 1,
//! pre-chorus, chorus, bridge, tag, outro, 20 bars) and a `default`
//! arrangement that plays the chorus twice (8 positions, 48 s). One quiet
//! stereo `keys` stem holds a soft chord whose root changes with every
//! section, so a jump can be heard; the click is generated by the player.

use std::f64::consts::TAU;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use domain::{
    Arrangement, SectionMarker, SectionType, SongPackage, Stem, StemRole, TempoPoint,
    TimeSignaturePoint,
};
use hound::{SampleFormat, WavSpec, WavWriter};

const RATE: u32 = 48_000;
const BAR: u64 = 2 * RATE as u64;
/// Peak level of the chord, well below full scale.
const LEVEL: f64 = 0.12;

/// Section id, type, number, bars, and the root of its chord in Hz.
const SECTIONS: &[(&str, SectionType, Option<u32>, u64, f64)] = &[
    ("intro", SectionType::Intro, None, 2, 220.00),
    ("verse", SectionType::Verse, Some(1), 4, 196.00),
    ("pre", SectionType::PreChorus, None, 2, 174.61),
    ("chorus", SectionType::Chorus, None, 4, 261.63),
    ("bridge", SectionType::Bridge, None, 4, 146.83),
    ("tag", SectionType::Tag, None, 2, 233.08),
    ("outro", SectionType::Outro, None, 2, 220.00),
];

fn main() -> ExitCode {
    let Some(dir) = std::env::args_os().nth(1).map(PathBuf::from) else {
        eprintln!("usage: demo_song <DIR>");
        return ExitCode::from(2);
    };
    match write(&dir) {
        Ok(()) => {
            println!("wrote a demo song to {}", dir.display());
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("error: {error}");
            ExitCode::from(1)
        }
    }
}

fn write(dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let mut start = 0;
    let mut sections = Vec::new();
    for &(id, section_type, number, bars, _) in SECTIONS {
        sections.push(SectionMarker {
            id: id.to_owned(),
            section_type,
            number,
            start,
        });
        start += bars * BAR;
    }
    let order = [
        "intro", "verse", "pre", "chorus", "bridge", "chorus", "tag", "outro",
    ];
    let package = SongPackage {
        format_version: 1,
        title: "Demo Song".to_owned(),
        artist: Some("Multitrack".to_owned()),
        sample_rate: RATE,
        key: None,
        tempo_map: vec![TempoPoint { at: 0, bpm: 120.0 }],
        time_signature_map: vec![TimeSignaturePoint {
            at: 0,
            numerator: 4,
            denominator: 4,
        }],
        stems: vec![Stem {
            id: "keys".to_owned(),
            file: "stems/keys.wav".to_owned(),
            part: "keys".to_owned(),
            role: StemRole::Track,
        }],
        sections,
        arrangements: vec![Arrangement {
            id: "default".to_owned(),
            name: "Default".to_owned(),
            sections: order.iter().map(|id| (*id).to_owned()).collect(),
            infinite_loop: Vec::new(),
        }],
    };
    fs::create_dir_all(dir.join("stems"))?;
    fs::write(dir.join("song.json"), package.to_json()?)?;

    let spec = WavSpec {
        channels: 2,
        sample_rate: RATE,
        bits_per_sample: 16,
        sample_format: SampleFormat::Int,
    };
    let mut writer = WavWriter::create(dir.join("stems/keys.wav"), spec)?;
    for &(_, _, _, bars, root) in SECTIONS {
        let frames = bars * BAR;
        for frame in 0..frames {
            let sample = chord(root, frame, frames);
            let value = (sample * f64::from(i16::MAX)).round() as i16;
            writer.write_sample(value)?;
            writer.write_sample(value)?;
        }
    }
    writer.finalize()?;
    Ok(())
}

/// A major triad on `root` at `frame` of a section of `frames`, with short
/// fades at both ends so the seams between sections do not click.
fn chord(root: f64, frame: u64, frames: u64) -> f64 {
    let t = frame as f64 / f64::from(RATE);
    let tone: f64 = [1.0, 1.259_921, 1.498_307]
        .iter()
        .map(|ratio| (TAU * root * ratio * t).sin())
        .sum::<f64>()
        / 3.0;
    let edge = (RATE / 100) as u64;
    let envelope = (frame.min(frames - frame) as f64 / edge as f64).min(1.0);
    LEVEL * tone * envelope
}
